SELECT CASE WHEN c.age >= 61 THEN 'high' WHEN c.age >= 38 THEN 'mid' ELSE 'low' END AS age_bucket, MONTH(c.signup_date) AS signup_month, SORT_ARRAY(COLLECT_SET(s.browser)) AS browser_list, COUNT(DISTINCT s.customer_id) AS unique_customers FROM sessions s LEFT OUTER JOIN customers c ON s.customer_id = c.id WHERE HOUR(s.started_at) BETWEEN 8 AND 12 GROUP BY CASE WHEN c.age >= 61 THEN 'high' WHEN c.age >= 38 THEN 'mid' ELSE 'low' END, MONTH(c.signup_date) ORDER BY 2 DESC
